#!/usr/bin/env python3
import sys


def rec(N, b):
    if N == 0:
        return []
    buf = -1
    for i in range(N):
        if b[i] > i+1:
            return [-1]
        if b[i] == i+1:
            buf = i
    if buf == -1:
        # ここはありえないはずではある
        print("ありえない")
        return [-1]
    a = b.pop(buf)
    return rec(N-1, b) + [a]


def solve(N, b):
    for x in rec(N, b):
        print(x)
    return

# Generated by 1.1.3 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)


def main():
    N = int(input())
    b = [int(x) for x in input().split()]
    solve(N, b)


if __name__ == '__main__':
    main()
